import{_ as l,a as t,b as i}from"./chunks/db1046de947e25458552.Dkom2r4H.js";import{_ as o,C as r,o as n,c as s,j as e,a as h,E as c,a6 as u}from"./chunks/framework.CnPv4DE1.js";const P=JSON.parse('{"title":"6个月后，你将不再是现在的你（快速精通任何事物）","description":"","frontmatter":{"title":"6个月后，你将不再是现在的你（快速精通任何事物）","originalTitle":"You Won’t Be The Same Person In 6 Months (Master Anything, Fast)","date":"2023-12-08","originalUrl":"https://thedankoe.com/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast/","minutes":18,"sourceHash":"23b77336272ba79a864538489e4771da4864da7bfcfe1ce6d15b010b545f9bb5","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast/"}]]},"headers":[],"relativePath":"letters/you-wont-be-the-same-person-in-6-months-master-anything-fast.md","filePath":"letters/you-wont-be-the-same-person-in-6-months-master-anything-fast.md"}'),m={name:"letters/you-wont-be-the-same-person-in-6-months-master-anything-fast.md"};function d(b,p,f,_,g,k){const a=r("ArticleMeta");return n(),s("div",null,[p[0]||(p[0]=e("h1",{id:"_6个月后-你将不再是现在的你-快速精通任何事物",tabindex:"-1"},[h("6个月后，你将不再是现在的你（快速精通任何事物） "),e("a",{class:"header-anchor",href:"#_6个月后-你将不再是现在的你-快速精通任何事物","aria-label":'Permalink to "6个月后，你将不再是现在的你（快速精通任何事物）"'},"​")],-1)),c(a),p[1]||(p[1]=u('<p><a href="https://www.youtube.com/embed/h_r6Mo8EDic?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><blockquote><p>大多数人，尽管自己并不知道，但其实都在沉睡。他们生来就在沉睡，活着时在沉睡，结婚时在沉睡，生儿育女时在沉睡，直到死去都在沉睡，从未真正醒来。他们永远无法理解我们称之为“人类存在”的这件美好而动人的事。——安东尼·德·梅洛 (Anthony De Mello)</p></blockquote><p>人们正过着自动驾驶般的生活。</p><p>每个人在孩童时期，就被社会分配了各种目标。</p><p>目标的实现需要一个系统。</p><p>一个系统需要经过不断试错才能变得高效。</p><p>为了生存，你有着走路、发声和说话的生物学目标。</p><p>尽管它们现在对你来说轻而易举，但情况并非一直如此。</p><p>你的大脑从环境中接收到负面反馈，从而促使这些系统变得高效，以实现你生存的目标。</p><p>当你犯错时，你的父母要么责骂你，要么为你指明正确的方向。</p><p>你开始爬行，然后跌跌撞撞，接着像个平衡感极差的学步儿童一样走路，而现在，你（希望如此）走起路来，就像奥运金牌得主在空中翻腾并稳稳落地一样自如——因为他们为实现那个目标练习了足够长的时间。</p><p>学会走路只是个开始。</p><p>那么，上学、找一份高薪工作，然后在几乎没剩多少时间享受生活的年纪退休，这些目标又如何呢？</p><p><strong>社会就是一个行为系统。</strong></p><p>这正是当你刚学会理解自己所说的语言时，他们强行注入你大脑的三个大目标。</p><p>99% 的人只是以导向那些目标的方式，在诠释日常遭遇的各种情况。</p><p>99% 的人在不知不觉中，练习着各种技能并给自己的大脑编程，以过上平庸的生活。</p><p>大众正被驱赶向一种毫无成就感的生活，因为构成他们心智、身份、视角和认知体系的系统，正随着年龄的增长而变得越来越高效。</p><p><strong>人们往往太晚才意识到的一个真相：</strong></p><p>成功不是计划出来的，它是自动发生的。</p><p>成功人士——无论他们是否有意识——都拥有一个被编程为去实现导向成功之目标的大脑。</p><p>把你的大脑想象成一个嵌套系统的结构。</p><p>你的身份、视角和对情况的认知都是系统，它们按照这个顺序相互输入并相互强化。</p><p>我在这里是为了让你意识到那些能在任何事业中带来自动成功的系统。</p><h2 id="目标-系统" tabindex="-1">目标 &gt; 系统 <a class="header-anchor" href="#目标-系统" aria-label="Permalink to &quot;目标 &gt; 系统&quot;">​</a></h2><p><img src="'+l+'" alt=""></p><p>过上你想要的生活，80% 归结于创造你自己的目标，而大多数人都是毫无思想的、屈从于社会目标的奴隶。</p><p>目标改变了你对情况的诠释方式，这影响了你的行动，进而重塑了你的身份，最终在岁月的复利下铸就了美好的生活。</p><p>除非你意识到问题的存在，否则你无法解决它。</p><p>除非问题影响到了某个目标，否则你无法意识到它的存在。</p><p>大多数人没有目标。大多数人害怕犯错。大多数人不给自己任何改善生活哪怕一个方面的机会。</p><p>如果你都不清楚自己想要什么，你就无法向别人传达你的需求。</p><p>这会让你陷入一个充满臆测和期待，却永远无法从生活中得到所求的人生。没人帮得了你，你也帮不了你自己。</p><p>如果你不对一个目标投入精力，你就不会体会到无法实现该目标时的痛苦。</p><p>偶尔喝点酒（不到酗酒程度）本来不是什么问题，直到它阻碍了我实现拥有一段美满关系的目标。</p><p>我从来没把它当回事儿，直到有人提醒我，在那之后的几天里我都表现得“不太对劲”。我本以为自己表现得很正常。如果我从未在经营一段关系这个目标上投入精力，或者认为它比晚餐时喝两杯的乐趣更重要，我就永远不会注意到它的负面影响。这就是我想表达的核心。</p><p>大多数人对于想从目标中获得什么并没有清晰的愿景，因此他们行为的负面影响也就被忽视了。</p><p>你的坏习惯似乎不值得戒掉，因为你没有需要你发挥 100% 能力去承担的责任（或者你没有把这些责任放在首位）。</p><p>如果那些责任的重要性超越了你的坏习惯带来的快感，你绝对会毫不犹豫地停止作恶。</p><p>目标与身份是交织在一起的。</p><p>人类在概念层面上生存。</p><p>当构成我们“自我”的事物受到威胁时，我们就会感到受到威胁。</p><p>健美运动员如果身处一个对训练和饮食难以把控的环境，就会感到压力和痛苦。</p><p>惯例是一套能够让大脑保持秩序的实用目标。一个搬到新地方或长期旅行的作家，在他们的大脑开始靠新系统运转之前，会经历一段充满压力的适应期。如果他们无法在常规的惯例中写出好东西，他们就会感到受到威胁，因为“他们是谁”这个身份可能会随之消亡。</p><p>关于惯例的重要性——哪怕你觉得自己不需要或者没有——我在<a href="/letters/the-daily-routine-that-changed-my-life-4-focus-habits">改变我人生的日常惯例（4个专注习惯）</a>中有过详细探讨。</p><p>这里普遍存在的误解是，你认为自己要么有目标，要么没目标。</p><p>你的大脑是一张由有意识和无意识目标交织而成的网，并伴随着实现它们的系统。</p><p>你在孩童时期有走路、进食和生存的生物学目标。这对大多数人来说已经是本能，因为他们已经练习过了。</p><p>这个系统很高效。</p><p>根据你成长的环境，你可能会有一些文化目标，比如融入群体，并遵循该文化所认定的安全路径。</p><p>如果你用新的刺激条件化自己（不断自我教育），直到你的身份“不实现新目标就无法存活”的地步——那么无论这些目标是什么，你都必然能轻而易举地实现。如果你想拥有成功的商业、伴侣关系，或任何不同寻常的东西，你必须通过改变“你是谁”，来从根本上改变你大脑运作所依赖的目标。</p><p>为了改变你是谁，你必须去学习、去实践、去体验新信息，从而为你大脑中被社会强行植入的错误线路重新编程。</p><h2 id="大脑是一个帮你实现目标的系统" tabindex="-1">大脑是一个帮你实现目标的系统 <a class="header-anchor" href="#大脑是一个帮你实现目标的系统" aria-label="Permalink to &quot;大脑是一个帮你实现目标的系统&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><blockquote><p>人类天生就是追求目标的生物。因为人类是“被这样设计出来的”，所以除非他以被设定好的方式运作——作为一个目标追求者——否则他就不会感到快乐。因此，真正的成功和真正的快乐不仅相伴而生，而且彼此相互促进。——麦克斯韦尔·沃尔兹 (Maxwell Waltz)</p></blockquote><p>这句出自《心理控制术》（<em>Psycho Cybernetics</em>）的名言，可以与《心流》（<em>Flow</em>）中的另一句话联系起来。</p><blockquote><p>最优的内心体验状态是意识中存在秩序的状态。当心理能量——或注意力——投入到现实目标中，并且技能与行动机会相匹配时，这种情况就会发生。追求目标会在意识中带来秩序，因为一个人必须将注意力集中在手头的任务上，暂时忘记其他一切。——米哈里·契克森米哈赖 (Mihaly Csikszentmihalyi)</p></blockquote><p>人类是目标导向的生物。</p><p>而目标创造了系统。</p><p>没有目标，系统就不存在（接招吧，詹姆斯·克利尔）。</p><p>大脑在生存方面有两个关键目的：</p><ol><li>实现已知的目标</li><li>发现未知的目标</li></ol><p>大脑是一台信息处理和模式识别机器，基于我们的意识水平，我们可以对其施加一定程度的控制。</p><p>大脑是一个系统——包含一套复杂的系统集——它接收、拒绝并利用信息，以协助实现你输入给它的目标。</p><p>如果你总是把焦点放在负面结果上，它们就会变成现实，然后你会把你生活中的不幸怪罪于除你自己以外的所有人。</p><blockquote><p>认为自己是个“失败型人格”的人总能找到方法搞砸，不管他初衷多好，就算机会直接砸在他怀里也一样。那些认定自己是不公的受害者、是“命中注定要受苦”的人，总是能找到证实自己观点的外部环境。——麦克斯韦尔·沃尔兹 (Maxwell Waltz)</p></blockquote><p>换句话说，如果你认为你能，你就能；如果你认为你不能，你就不能。</p><p>在你心智的最深处，如同提线木偶大师一般操控一切的，是你的身份。</p><p>在这封信的语境下，身份与自我形象或个性是同义词。</p><p>你的身份是一个由观念、信念、价值观和标准组成的系统，正是它塑造了你的视角。</p><p>你的视角就像相机的镜头。</p><p>你可以推近和拉远。</p><p>你可以聚焦在画面的某个部分——同时虚化背景——或者聚焦于整个画面的所有细节。</p><p>你的视角影响着你对各种情况的认知。</p><p>意思是，你的身份会限制它所能感知到的信息；如果接收到的信息与它的信念、价值观或标准不符，它就会将其排斥在外。</p><p>你的大脑会自动接收和拒绝那些有助于实现已被编程进你脑海中目标的信息。</p><p>如果你想找份工作，多巴胺就会发出信号，凸显那些帮你得到那份工作的信息和机会的重要性。</p><p>你在书里划的重点会反映这个目标。你与（任何人）交谈的方式会反映这个目标。你在社交媒体上互动的内容也会反映这个目标（而算法会通过向你展示更多此类信息，来加深这种身份的根基，无论好坏）。</p><p>如果你想辞职，多巴胺同样会发挥作用，只不过对象换成了产生截然相反效果的信息。</p><p>你的谷歌搜索记录将从“2024 年最值得从事的职业”变成“2024 年最适合创业的项目”。</p><p>或者，你会更有冲动去查看 <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">数字经济学（Digital Economics）</a>，在那里，我教你解构自己的身份，并将其转变为一个盈利的一人企业。</p><p>哪怕是在读小说这样的读物时，你划的重点也会与那些拥有不同目标的人截然不同。</p><p>无论是否有意识，我们都在不断强化着自己可能很平庸的身份，而这决定了我们人生的走向。对大多数人来说，这将是负面的。</p><p>如果你想改变人生的结果，先改变你是谁。</p><p>如果你想改变你是谁，先改变人生的方向。</p><p>把自己暴露在新的经历、环境和信息中，给大脑一个机会去发现你可以采纳的新目标，这些目标将载着你走向更美好的未来。</p><h2 id="精通之道——如何快速学习任何事物" tabindex="-1">精通之道——如何快速学习任何事物 <a class="header-anchor" href="#精通之道——如何快速学习任何事物" aria-label="Permalink to &quot;精通之道——如何快速学习任何事物&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>可以毫不夸张地说，你将需要学习……非常多东西。</p><p>教育能拓宽你的心智。</p><p>它为你引入新颖的视角。</p><p>它增加大脑中的多巴胺，作为源源不断的能量来源。</p><p>它赋予你知识，让你能够目标明确地采取行动。</p><p>它让你接触到那些你尚未意识到的潜能。</p><p>持续不断的教育输入会增加你遭遇意义非凡之事的几率。</p><p>当你的神经系统发出你应该集中注意力的信号时，有意义的事件通常就发生在已知边界的边缘。</p><p>当你有一只脚踏入未知领域时，你才勉强能够消化现实的新层面，并将这些信息付诸实用。</p><p>成为你想成为的人，是你一生中能致力于的最痛苦但也最有回报的过程。</p><p>当你意识到，你现在所处位置的痛苦与快乐，远不及那种“无法看到自己到底有多大潜能从而错失回报”的痛苦时，你就踏上了这条路。</p><p>既然如此，让我们来讨论一下，在你跋涉着成为一个全新的自己时，如何掌握几乎任何事物：</p><h3 id="_1-拓宽你的心智" tabindex="-1">1) 拓宽你的心智 <a class="header-anchor" href="#_1-拓宽你的心智" aria-label="Permalink to &quot;1) 拓宽你的心智&quot;">​</a></h3><p>所有真正的改变都是身份的改变。</p><p>你的心智水平决定了你的身份能够拥有什么样的价值观、信念和标准。</p><p>你不关心全球性问题，是因为你还没有解决那些限制你心智、让你无法意识到这些问题有多重要的个人问题。</p><p>人类的目的是将你的心智水平拓展至宇宙的高度。</p><p>你必须给自己留出空间，通过向未知领域抛下锚来发现新的目标。</p><p>设定一个宏大的目标，让它成为未知领域中的聚光灯。</p><p>你设定这个宏大目标并不是为了实用性或成就。</p><p>你设定它是为了获得愿景、方向以及过滤机会的标准。</p><p>专注于让它变得尽可能令人向往。</p><ul><li>如果你拥有世界上所有的钱，你平常的一天会是什么样？</li><li>你想生活在什么样的环境中？有具体的地点吗？你想去旅行吗？</li><li>你想要组建家庭吗？你希望那样的生活是什么样的？想象一下平凡的一天里与家人共度的时光。</li><li>你希望每天工作多长时间？如果你能做任何事，你想从事什么工作？</li><li>你希望自己的外表和状态是怎样的？描述一下你的身体状况、精力水平，以及你希望向世界呈现怎样的自己。</li><li>你理想中的一天是什么样的？规划出每一个小时。</li><li>列出你脑海中浮现的、关于你想为自己构建的具体未来的任何其他事情。</li></ul><p>为了让这变得更有效力，将这个愿景转化为一个反向愿景，以此来完善你理想自我的视角：</p><ol><li>你生命中最糟糕的折磨是什么？</li><li>写出关于你愿景的每一个问题的反面。</li></ol><p>为了获得更强大的火力，制作一块愿景板。在剪贴簿、软件或墙上添加图片，让那个未来变得更加触手可及。</p><p>记住，没有什么是永恒的。</p><p>当你在这条路上跋涉时，你会发现关于你愿景的些许端倪。当发现自己不想要什么时，要对改变自己想要的东西保持开放的心态。</p><p>达不到愿景的痛苦应该超过平庸带来的快乐。</p><p>一个宏大的目标不仅能提供愿景，还能在需要做决定时为你提供一个可以采用的视角。</p><p>用你的愿景来过滤你收到的每一个机会。</p><p>除了那些与你想成为的人相契合的事物，对其他一切说“不”。</p><p>开始通过有意识的选择，使你心智运行的错误程序短路。</p><h3 id="_2-目标的层级" tabindex="-1">2) 目标的层级 <a class="header-anchor" href="#_2-目标的层级" aria-label="Permalink to &quot;2) 目标的层级&quot;">​</a></h3><p>这就是我创建 <a href="https://thedankoe.com/planner" target="_blank" rel="noreferrer">FOCI Planner</a> 的原因：</p><p>大多数人不需要动力，他们需要的是清晰度。</p><p>有序的心智是快乐的，而自我生成的层级目标，会让令人沮丧的干扰很难渗透进你的意识。</p><p>大目标是为了提供愿景和过滤标准，而小目标则是为了实用性和进展。</p><p>现在，将你的愿景分解为你生活中各个领域的目标——心智、身体、精神、事业。在这里，人际关系与精神是同义词。</p><p>是的，这会很耗时。把这些写下来存放在安全的地方，这样你就可以在前进的过程中随时进行修改。</p><p>针对这4个生活领域，设定：</p><ul><li>10年目标</li><li>1年目标</li><li>月度目标</li><li>每周目标</li></ul><p>然后，每一天，你要写下3-5个优先任务，这些任务要从最基础的地方推动你朝着这些目标取得实质性进展。</p><p>每天早上第一件事就是搞定这些任务，趁着各种责任和干扰还没来得及苏醒。</p><p>我在这封信中谈到了我的深度工作（deep work）结构：<a href="/letters/change-your-life-in-6-months-my-deep-work-routine">在6个月内改变你的生活（我的深度工作惯例）</a>。</p><h3 id="_3-如何学习" tabindex="-1">3) 如何学习 <a class="header-anchor" href="#_3-如何学习" aria-label="Permalink to &quot;3) 如何学习&quot;">​</a></h3><p>学习源于挣扎，而不是死记硬背。</p><p>你无法通过整天看教程来学习。</p><p>你是通过构建项目和面对现实来学习的。</p><p>项目是你可以衡量和迭代的目标。</p><p>所以，把你的一些1年目标或月度目标变成一个项目。</p><ul><li>构思一种方法来构建一些有形的东西（你必须付诸行动）</li><li>写下你能达到的里程碑。</li><li>在备忘录应用或笔记本上创建一个大纲。</li><li>将脑海中浮现的任何想法倾倒出来。</li></ul><p>为心智、身体、财务和精神发展做这件事。</p><p>这会为你的大脑做好准备，以接受由模式识别引发的有意义的多巴胺。</p><p>你的项目为你对各种情况的感知添加了额外的“规则”。</p><p>现在，你在自我教育以及在构建过程中解读反馈时，就有了一个可以记下接收到的高信号信息的地方。</p><p>先开始，再学习。你必须将学习与构建同步进行，才能真正学到东西。</p><p>当你构建一些东西时，你会遇到真实的问题，这些问题需要更高水平的心智来解决。</p><p>只有到那时，你才能去寻找信息来拓宽心智并解决这些问题。整天看教程是不可能做到这一点的。</p><h3 id="_4-技能是技巧的集合" tabindex="-1">4) 技能是技巧的集合 <a class="header-anchor" href="#_4-技能是技巧的集合" aria-label="Permalink to &quot;4) 技能是技巧的集合&quot;">​</a></h3><p>构建项目并不是学习的终点。</p><p>为了构建一个项目，你必须在过程中掌握技能。</p><p>但你并非去“学习一项技能”。</p><p>你学习一个技巧，对其进行试验，并不断添加新的技巧，直到你能以某种方式将它们结合起来，从而获得你想要的结果。</p><p>你不能把 Photoshop 当作一项技能来学。</p><p>你要创建一个项目，寻找一种技巧来完成其中的一个方面，然后不断学习其他技巧，直到完成这个项目。</p><p>试图去学习软件本身几乎毫无用处，而且要花长得多的时间。</p><p>去除图像背景有超过10种不同的技巧。</p><p>了解多种技巧能让你从几乎任何场景中无缝地去除背景。</p><p>你不能把文案写作当作一项技能来学。</p><p>你学习的是用于以下方面的技巧：</p><ul><li>捕获注意力</li><li>维持注意力</li><li>提升你的产品或想法的感知价值</li><li>等等</li></ul><p>每一项都有几十种技巧，你学得越多，作为一项技能的文案写作就越出色。</p><p>在 <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a> 中，每个模块都是一项供你练习的技巧，以此让你在新经济中成为一名高薪作家。</p><p>万物皆技能。</p><p>生活是一项将健康、财富和人际关系统括为技能的技能，直至将其分解为你可以用一生去练习的技巧，从而掌控生活本身。</p><p>所有的技能都是心智层面的。</p><p>技能就是心智系统，它会随着练习变得更加高效，以达到你想要的结果。</p><h3 id="_5-重塑自我" tabindex="-1">5) 重塑自我 <a class="header-anchor" href="#_5-重塑自我" aria-label="Permalink to &quot;5) 重塑自我&quot;">​</a></h3><p>把你的心智看作现实的消化系统。</p><p>如果你吃得太多或动得太少，你就无法消化代谢那些经验。</p><p>如果你吃得太少或动得太多，你就会感到饥饿和焦躁。</p><p>当你吃得恰到好处时，你就创造了一个有利于心智肌肉生长的环境。你在现实中向着你的目标跋涉。你进入了一个纯粹进步的季节，那种感觉棒极了。</p><p>你已经创造了足够深地跃入未知领域所必需的边界、限制或清晰度。</p><p>带着愿景、目标和项目，你已为全新的生活做好了准备。</p><p>你所要做的就是勇敢一跃。</p><p>把自己投身于一个全新的物理或数字环境中。</p><ul><li>搬到国家的另一端。</li><li>取关网上的所有人。</li><li>关注那些与你未来一致的人。</li><li>改变你的穿着、你购物的地方以及你见的人。</li><li>让你的大脑沉浸在那些你一直推迟阅读的书籍中。</li></ul><p>让所有的信息，或者说现实，都与你想成为的人对齐。</p><p>一开始你会感到受到威胁，直到你拓展进入你的新身份。</p><p>你的旧身份将会消亡，因为它得不到强化它的信息，从而被饿死。</p><p>在你人生中这个极其困难却又极其有意义的转折点上，一定要坚持住。</p><h3 id="_6-大自然的指南针" tabindex="-1">6) 大自然的指南针 <a class="header-anchor" href="#_6-大自然的指南针" aria-label="Permalink to &quot;6) 大自然的指南针&quot;">​</a></h3><p>人们太害怕犯错，以至于犯下了最大的错误：不犯错。</p><p>你无法避免犯错。</p><p>它们是大自然的指南针。</p><p>不犯错的人，没有给自己创造取得成功的机会。</p><p>想象一辆自动驾驶汽车。</p><p>多年来，它不断接收负面反馈，以此来优化塑造汽车“心智”的系统。</p><p>它能在道路上轻松导航，甚至可以说比人类驾驶更安全。</p><p>尽管我们通常不这么认为，但这辆自动驾驶汽车在能够真正到达有意义的目的地之前，犯下了成百上千万甚至上十亿次的错误。</p><p>你必须与你的大目标保持一致去行动，通过错误带来的负面反馈，形成你心智赖以运作的新系统。</p><ul><li>养成强迫自己采用最高版本自我的视角来看待问题的习惯。</li><li>让这个镜头为你揭示出可以采取行动的新机会。</li><li>当你犯错时（因为你必然会犯错），把它作为你下一步选择的方向。</li></ul><p>随着时间的推移，你甚至都没意识到，自己已经在选择发展的任何技能上成为了一名艺术家。</p><p>你将能够像走路一样轻松地实现大多数人认为困难的目标（而大多数人还在爬行）。</p><h3 id="_7-自我实验解决问题" tabindex="-1">7) 自我实验解决问题 <a class="header-anchor" href="#_7-自我实验解决问题" aria-label="Permalink to &quot;7) 自我实验解决问题&quot;">​</a></h3><p>你的生活以及构成它的项目应该被当作科学项目来对待。</p><p>要想解决达成目标路上的问题：</p><ul><li>假设一个结果（源于你的目标）</li><li>实验各种技巧（为了获取技能）</li><li>记录过程（作为一个项目）</li><li>在结果上加倍投入（作为一种解决方案）</li></ul><p>现在，你有了经验、技能、一个可以转化为商业产品的项目，以及一个能在创作者经济（creator economy）中收费的解决方案。</p><p>我在 <a href="/letters/the-anti-niche-why-being-nicheless-makes-you-irreplaceable">反细分领域（为什么变得没有细分领域会让你不可替代）</a> 中讨论过这个话题。</p><p>自我实验是彻底解决你问题的唯一方法。</p><p>假设你的目标是练出六块腹肌。</p><p>你在寻找解决方案，他们告诉你纯素食主义能解决你所有的问题，而在一种未开化的状态下，你：</p><ul><li>清理了你的饮食</li><li>把他们的建议奉为圭臬去遵循</li><li>看到了他们提到的结果</li></ul><p>然后，你依附于那种饮食意识形态并成为了它的布道者。你把别人通过不同方式获得的结果归功于纯素食主义，并将任何质疑你的人妖魔化。</p><p>显然，这是危险的，这就是低意识水平的定义。</p><p>实际上，发生的事情与纯素食主义无关：</p><ul><li>你吃了更多营养密集的食物</li><li>你的行动起到了维持你纯素食者身份的作用</li><li>通过遵循严格的营养机制，你获得了清晰度（而不是混乱）</li></ul><p>在这种情况下，纯素食主义仅仅是一种让你的心智变得有序的形式（保持一定程度的心流（flow）状态），让你能够遵循健康的原则——但你却把它归结为了一种方法。</p><p>现在，如果你尝试吃素一个月，吃纯肉饮食一个月，生酮饮食一个月，再尝试灵活饮食一个月，你将会：</p><ul><li>在各种饮食法之间建立联系，从而揭示健康的基本原理（模式识别 = 多巴胺）。</li><li>挑选出你喜欢的特定方法，这意味着它们将带来可持续的结果。</li><li>完善出一个完美契合你个人天性的系统。</li></ul><p>然后，一旦健康的生活方式变得毫不费力，你就可以在你的财务、社交生活、浪漫关系、精神追求或生活的任何其他领域做同样的事情。</p><p>如果你的感情关系遇到了问题，那就聘请一位治疗师，去看看YouTube上的大师，去参加静修营，然后尝试各种选项，直到找到正确的解决方案。</p><p>如果你的业务没有增长，那就买个课程，请个教练，测试一款新软件，拉远视角，并制定一个新策略。</p><p>总有办法解决你的问题，而当你死死抓住一个解决方案（那可能无法一劳永逸地解决问题）时，你就剥夺了自己的这种力量。</p><p>把生活的每一个领域都看作是一个项目，同时也是一项技能，在这个过程中，你要不断收集各种技巧，以精通该领域。</p><h3 id="精通方法论-总结" tabindex="-1">精通方法论：总结 <a class="header-anchor" href="#精通方法论-总结" aria-label="Permalink to &quot;精通方法论：总结&quot;">​</a></h3><p>这样做，你就能极其迅速地达成目标，以至于别人会在人生这场游戏中找你要“作弊码”：</p><ol><li><strong>用一次愿景构想环节来拓展你的思维。</strong> 这种视角将让你能够设定新目标并发现生活的新潜能（从而让你打破狭隘的思维并取得更大成就）。</li><li><strong>创建一个目标层级体系，为你的生活带来清晰度。</strong> 你需要用实际的目标来填平你现状与你想去的地方之间的鸿沟。</li><li><strong>将你的目标转化为项目，以便你能同步进行构建和学习。</strong> 项目就是被衡量、被追踪和被改进的目标。</li><li>不要学习技能，要获取技巧。你的技能水平取决于你的工具箱中有多少能够解决棘手问题的技巧。</li><li><strong>用信息超载来重塑自己</strong> 改变你的物理和数字环境，强迫自己敞开心扉并发现新的潜能。</li><li><strong>把错误当作你系统中的负面反馈。</strong> 你没有其他方法可以测试出能获得更好结果的东西。</li><li><strong>把你的生活当作一个科学项目。</strong> 在健身、商业、知识和人际关系中痴迷于实验。</li></ol><p>感谢阅读。</p><p>下周见，</p><p>Dan</p><hr><p><a href="/en/letters/you-wont-be-the-same-person-in-6-months-master-anything-fast">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',223))])}const x=o(m,[["render",d]]);export{P as __pageData,x as default};
